#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_LINE GPIO_PIN

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int value;
    int ret;

    /* Register signal handler for Ctrl+C */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "my_app", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop */
    while (keep_running) {
        /* Read GPIO value */
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        /* Set GPIO value (output) */
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        /* Print GPIO state */
        printf("GPIO %d: %d\n", GPIO_LINE, value);

        /* Wait 5 seconds */
        sleep(5);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

