// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0200  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the ADS1115 configuration register
int write_config_register(int fd, uint16_t config_value) {
    uint8_t buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the conversion register and return the 16-bit ADC value
int16_t read_conversion_register(int fd) {
    uint8_t buf[1];
    uint8_t read_buf[2];

    buf[0] = ADS1115_REG_CONVERT;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (int16_t)((read_buf[0] << 8) | read_buf[1]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure the ADS1115 for single conversion, AIN0, +/-4.096V, 128 SPS
        uint16_t config_value = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

        // Write the configuration to the ADS1115
        if (write_config_register(i2c_fd, config_value) < 0) {
            fprintf(stderr, "Error writing config register, exiting.\n");
            break;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        int16_t adc_value = read_conversion_register(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading conversion register, exiting.\n");
            break;
        }

        // Print the ADC value to standard output
        printf("%d\n", adc_value);

        // Wait for 0.5 seconds
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

