#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

int main() {
    int i, duty_cycle;
    FILE *fp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode to output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open standard output for reporting
    fp = stdout;
    if (fp == NULL) {
        fprintf(stderr, "Failed to open standard output\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Set duty cycle
        for (i = 0; i < 100; i++) {
            duty_cycle = i * 10; // Increment duty cycle by 10%
            gpioPWM(PWM_GPIO, duty_cycle);
            fprintf(fp, "PWM: %d\n", duty_cycle);
            fflush(fp); // Flush the buffer to ensure immediate output
            usleep(500000); // 0.5 seconds
        }

        // Reverse direction
        for (i = 100; i > 0; i--) {
            duty_cycle = i * 10;
            gpioPWM(PWM_GPIO, duty_cycle);
            fprintf(fp, "PWM: %d\n", duty_cycle);
            fflush(fp);
            usleep(500000);
        }
    }

    // Clean up
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio

    return 0;
}

