void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 2; // Indicate that both edges have been received
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int start_tick, int end_tick) {
    double diff = (double)(end_tick - start_tick);
    double distance = (diff / 1000000.0) * SPEED_OF_SOUND / 2.0; // Divide by 2 for one-way distance
    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("HC-SR04 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        trigger_pulse();

        // Wait for echo to be received or timeout
        int timeout_count = 0;
        while (echo_received != 2 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1us
            timeout_count++;
        }

        if (echo_received != 2) {
            fprintf(stderr, "Timeout waiting for echo\n");
            echo_received = 0; // Reset echo_received flag
            continue;           // Skip to the next iteration
        }

        // Calculate distance
        double distance = calculate_distance(echo_start_tick, echo_end_tick);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Wait 60 seconds
        sleep(60);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

