#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read temperature from SI7021
float read_temperature() {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature measurement command: %d\n", result);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        gpioDelay(30); // Wait for measurement (datasheet specifies 20ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %d\n", result);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        unsigned int raw_temp = (buf[0] << 8) | buf[1];
        float temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return temperature;
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1000.0; // Indicate error
}

// Function to read humidity from SI7021
float read_humidity() {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, MEASURE_HUMID_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing humidity measurement command: %d\n", result);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        gpioDelay(30); // Wait for measurement

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading humidity data: %d\n", result);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        unsigned int raw_humidity = (buf[0] << 8) | buf[1];
        float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
        return humidity;
    }

    fprintf(stderr, "Failed to read humidity after multiple retries.\n");
    return -1000.0; // Indicate error
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        float humidity = read_humidity();

        if (temperature > -999.0 && humidity > -999.0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(5);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_PGA_4_096V 0x0000 // +/- 4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int write_i2c_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115 for single-shot mode, +/-4.096V, 128 SPS
    uint16_t config_value = CONFIG_OS_SINGLE | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;
    if (write_i2c_word(i2c_fd, ADS1115_REG_CONFIG, config_value) < 0) {
        fprintf(stderr, "Error configuring ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion result
    uint16_t conversion_value;
    if (read_i2c_word(i2c_fd, ADS1115_REG_CONVERT, &conversion_value) < 0) {
        fprintf(stderr, "Error reading conversion result\n");
        close(i2c_fd);
        return 1;
    }

    // Print the conversion result
    printf("Conversion Value: %d\n", conversion_value);

    // Take two more readings with a 1-second delay
    for (int i = 0; i < 2; i++) {
        // Reconfigure for single-shot mode
        if (write_i2c_word(i2c_fd, ADS1115_REG_CONFIG, config_value) < 0) {
            fprintf(stderr, "Error reconfiguring ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete
        usleep(10000);

        // Read conversion result
        if (read_i2c_word(i2c_fd, ADS1115_REG_CONVERT, &conversion_value) < 0) {
            fprintf(stderr, "Error reading conversion result\n");
            close(i2c_fd);
            return 1;
        }

        // Print the conversion result
        printf("Conversion Value: %d\n", conversion_value);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

