#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define timeout duration in microseconds
#define TIMEOUT 50000 // 50ms

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to measure distance using HC-SR04
float measure_distance()
{
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse duration
    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT)
    {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT)
    {
        fprintf(stderr, "Error: HC-SR04 did not respond within timeout.\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT)
    {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT)
    {
        fprintf(stderr, "Error: HC-SR04 did not respond within timeout.\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    uint32_t pulse_duration = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_duration * 0.000001) * 34300 / 2
    float distance = (float)pulse_duration * 0.0343 / 2.0;

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Sensor\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate)
    {
        // Measure distance
        float distance = measure_distance();

        // Print distance to standard output
        if (distance >= 0.0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Error: Could not measure distance.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

