#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT11_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht11(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_start, pulse_end;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30

    gpioSetMode(gpio, PI_INPUT);

    /* Read data */
    for (i = 0; i < 40; i++) {
        /* Wait for the start of the data bit (LOW) */
        int timeout = 0;
        while (gpioRead(gpio) == 1) {
            if (timeout++ > 100) return -1; // Timeout
            gpioDelay(1);
        }

        /* Measure the length of the HIGH pulse */
        pulse_start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            if (timeout++ > 100) return -1; // Timeout
            gpioDelay(1);
        }
        pulse_end = gpioTick();

        if (pulse_end - pulse_start > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* Check checksum */
    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        return -2; // Checksum error
    }

    /* Convert data to temperature and humidity */
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    result = read_dht11(DHT11_GPIO, &temperature, &humidity);
    if (result != 0) {
        fprintf(stderr, "DHT11 read failed: %d\n", result);
        gpioTerminate();
        return 1;
    }

    printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);

    gpioTerminate();
    return 0;
}

