#define LED4_PIN 22
#define LED5_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read the ADC value from the MCP3008
int read_adc(int channel)
{
    int ret = 0;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    ret = ioctl(0, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1)
    {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

