#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C address of the OPT3001
#define OPT3001_ADDR 0x44

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nClosing I2C device and exiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to the OPT3001
int opt3001_write_byte(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a word from the OPT3001
int opt3001_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];

    // Write the register address to be read
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read two bytes from the register
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the bytes into a 16-bit value
    *value = (buf[0] << 8) | buf[1];

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure the OPT3001 for continuous conversion mode
    if (opt3001_write_byte(i2c_fd, CONFIG_REG, 0x8520) < 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        close(i2c_fd);
        return 1;
    }

    // Read the temperature from the OPT3001
    uint16_t temperature_raw;
    if (opt3001_read_word(i2c_fd, RESULT_REG, &temperature_raw) < 0) {
        fprintf(stderr, "Failed to read temperature from OPT3001\n");
        close(i2c_fd);
        return 1;
    }

    // Convert the raw temperature to Celsius
    float temperature_celsius = ((float)temperature_raw / 128.0) * 165.0 - 40.0;

    // Print the temperature to standard output
    printf("Temperature: %.2f °C\n", temperature_celsius);

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

