#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = TIMEOUT_MS / 100; // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return 1;
    }

    printf("UART initialized. Reading data...\n");

    char buffer[256];
    ssize_t bytes_read;

    while (program_running) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("Error reading from UART");
                break;
            }
        } else {
            fprintf(stderr, "UART read error or timeout.\n");
            break;
        }
        usleep(10000); // Small delay to avoid busy-waiting
    }

    if (close(uart_fd) == -1) {
        perror("Error closing UART");
    }

    printf("UART closed. Exiting.\n");
    return 0;
}

