        token = strstr(line, "crc=YES");
        if (token == NULL) {
            fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
            retry++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        // Extract temperature
        token = strstr(line, "t=");
        if (token == NULL) {
            fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
            retry++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        char temp_str[10];
        strncpy(temp_str, token + 2, sizeof(temp_str) - 1);
        temp_str[sizeof(temp_str) - 1] = '\0'; // Ensure null termination

        *temperature = atof(temp_str) / 1000.0;

