// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D commands
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from HTU21D
int read_temperature(float *temperature) {
    char buf[3];
    int result;

    // Send temperature measurement command
    result = i2cWriteByte(i2c_handle, TRIGGER_TEMP_MEASURE);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 50ms)
    gpioDelay(50000);

    // Read temperature data
    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    unsigned int raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = -46.85 + 175.72 * (float)raw_temperature / 65536.0;

    return 0;
}

// Function to read humidity from HTU21D
int read_humidity(float *humidity) {
    char buf[3];
    int result;

    // Send humidity measurement command
    result = i2cWriteByte(i2c_handle, TRIGGER_HUMID_MEASURE);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 50ms)
    gpioDelay(50000);

    // Read humidity data
    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }

    // Convert raw data to humidity (%RH)
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = -6.0 + 125.0 * (float)raw_humidity / 65536.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read temperature
        result = read_temperature(&temperature);
        if (result == 0) {
            // Read humidity
            result = read_humidity(&humidity);
            if (result == 0) {
                // Print temperature and humidity
                printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);
            } else {
                fprintf(stderr, "Error reading humidity\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // This point will not be reached unless there's an error or the program is interrupted.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

