    for (i = 8; i < 16; i++) {
        temperature <<= 1;
        temperature |= data_bits[i];
    }

    for (i = 16; i < 24; i++) {
        checksum <<= 1;
        checksum |= data_bits[i];
    }

    for (i = 24; i < 32; i++) {
        data_bits[i - 24] = data_bits[i];
    }

    for (i = 32; i < 40; i++) {
        checksum <<= 1;
        checksum |= data_bits[i];
    }

    if ((checksum & 0xFF) != (data_bits[32] & 0xFF)) {
        fprintf(stderr, "Error: Checksum mismatch on pin %d\n", gpio_pin);
        return data; // Return default values on error
    }

    data.humidity = (float)humidity / 10.0;
    data.temperature = (float)temperature / 10.0;

    return data;
}

