        }

        if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
                perror("VIDIOC_QUERYCAP");
                close(fd);
                exit(1);
        }

        if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
                fprintf(stderr, "%s is no video capture device\n", dev_name);
                close(fd);
                exit(1);
        }

        if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
                fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
                close(fd);
                exit(1);
        }

        CLEAR(fmt);

        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = 640;
        fmt.fmt.pix.height = 480;
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
        fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

        if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
                perror("VIDIOC_S_FMT");
                close(fd);
                exit(1);
        }

        CLEAR(req);

        req.count = 4; // Number of buffers
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
                perror("VIDIOC_REQBUFS");
                close(fd);
                exit(1);
        }

        buffers = calloc(req.count, sizeof(*buffers));

        if (!buffers) {
                fprintf(stderr, "Out of memory\n");
                close(fd);
                exit(1);
        }

        for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
                struct v4l2_buffer buf;

                CLEAR(buf);

                buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory      = V4L2_MEMORY_MMAP;
                buf.index       = n_buffers;

                if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
                        perror("VIDIOC_QUERYBUF");
                        close(fd);
                        exit(1);
                }

                buffers[n_buffers].length = buf.length;
                buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

                if (MAP_FAILED == buffers[n_buffers].start) {
                        perror("mmap");
                        close(fd);
                        exit(1);
                }
        }

        for (i = 0; i < n_buffers; ++i) {
                struct v4l2_buffer buf;

                CLEAR(buf);

                buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory      = V4L2_MEMORY_MMAP;
                buf.index       = i;

                if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                        perror("VIDIOC_QBUF");
                        close(fd);
                        exit(1);
                }
        }

        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

        if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
                perror("VIDIOC_STREAMON");
                close(fd);
                exit(1);
        }

        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                close(fd);
                exit(1);
        }

        FILE *fp = fopen("image.mjpg", "wb");
        if (!fp) {
                perror("fopen");
                close(fd);
                exit(1);
        }

        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                close(fd);
                exit(1);
        }

        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
                perror("VIDIOC_STREAMOFF");
                close(fd);
                exit(1);
        }

        for (i = 0; i < n_buffers; ++i) {
                munmap(buffers[i].start, buffers[i].length);
        }

        free(buffers);

        close(fd);

        return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_22;
struct gpiod_line *line_27;

// Signal handler for Ctrl+C
void signal_handler(int sig);

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for GPIO 22 and GPIO 27
    line_22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line_22) {
        perror("Error getting GPIO line 22");
        gpiod_chip_close(chip);
        return 1;
    }

    line_27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line_27) {
        perror("Error getting GPIO line 27");
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_22, "output_22", 0) < 0) {
        perror("Error requesting GPIO line 22 for output");
        gpiod_line_release(line_27);
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_27, "output_27", 0) < 0) {
        perror("Error requesting GPIO line 27 for output");
        gpiod_line_release(line_22);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 22 to HIGH
        if (gpiod_line_set_value(line_22, 1) < 0) {
            perror("Error setting GPIO 22 HIGH");
            break;
        }

        // Set GPIO 27 to LOW
        if (gpiod_line_set_value(line_27, 0) < 0) {
            perror("Error setting GPIO 27 LOW");
            break;
        }

        // Print current state to standard output
        printf("GPIO 22: HIGH, GPIO 27: LOW\n");

        // Wait for 0.01 seconds
        usleep(10000);

        // Set GPIO 22 to LOW
        if (gpiod_line_set_value(line_22, 0) < 0) {
            perror("Error setting GPIO 22 LOW");
            break;
        }

        // Set GPIO 27 to HIGH
        if (gpiod_line_set_value(line_27, 1) < 0) {
            perror("Error setting GPIO 27 HIGH");
            break;
        }

        // Print current state to standard output
        printf("GPIO 22: LOW, GPIO 27: HIGH\n");

        // Wait for 0.01 seconds
        usleep(10000);
    }

    // Release GPIO lines
    gpiod_line_release(line_22);
    gpiod_line_release(line_27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (line_22) gpiod_line_release(line_22);
    if (line_27) gpiod_line_release(line_27);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

