// SSD1306 I2C address
#define SSD1306_I2C_ADDR 0x3C

// SSD1306 screen dimensions
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

// I2C file descriptor
int i2c_fd;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to write a command to the SSD1306
int ssd1306_command(uint8_t command) {
    uint8_t buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write command to SSD1306");
        return -1;
    }
    return 0;
}

// Function to write data to the SSD1306
int ssd1306_data(uint8_t data) {
    uint8_t buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write data to SSD1306");
        return -1;
    }
    return 0;
}

// Function to initialize the SSD1306
int ssd1306_init() {
    // Initialization sequence (refer to SSD1306 datasheet)
    if (ssd1306_command(0xAE) != 0) return -1; // Display off
    if (ssd1306_command(0xD5) != 0) return -1; // Set display clock divide ratio/oscillator frequency
    if (ssd1306_command(0x80) != 0) return -1; // --ratio
    if (ssd1306_command(0xA8) != 0) return -1; // Set multiplex ratio
    if (ssd1306_command(0x3F) != 0) return -1; // --height-1
    if (ssd1306_command(0xD3) != 0) return -1; // Set display offset
    if (ssd1306_command(0x00) != 0) return -1; // --offset
    if (ssd1306_command(0x40 | 0x00) != 0) return -1; // Set start line address
    if (ssd1306_command(0x8D) != 0) return -1; // Charge pump setting
    if (ssd1306_command(0x14) != 0) return -1; // --enable
    if (ssd1306_command(0x20) != 0) return -1; // Set memory addressing mode
    if (ssd1306_command(0x00) != 0) return -1; // --horizontal addressing mode
    if (ssd1306_command(0xA1) != 0) return -1; // Set segment re-map
    if (ssd1306_command(0xC8) != 0) return -1; // Set COM output scan direction
    if (ssd1306_command(0xDA) != 0) return -1; // Set COM pins hardware configuration
    if (ssd1306_command(0x12) != 0) return -1; // --alternative
    if (ssd1306_command(0x81) != 0) return -1; // Set contrast control
    if (ssd1306_command(0xCF) != 0) return -1; // --contrast
    if (ssd1306_command(0xD9) != 0) return -1; // Set pre-charge period
    if (ssd1306_command(0xF1) != 0) return -1; // --period
    if (ssd1306_command(0xDB) != 0) return -1; // Set VCOM deselect level
    if (ssd1306_command(0x40) != 0) return -1; // --level
    if (ssd1306_command(0xA4) != 0) return -1; // Display all points off
    if (ssd1306_command(0xA6) != 0) return -1; // Set normal display
    return 0;
}

// Function to clear the display buffer
void clear_display() {
    for (int i = 0; i < SSD1306_WIDTH * (SSD1306_HEIGHT / 8); i++) {
        ssd1306_data(0x00);
    }
}

// Function to display a string on the SSD1306
void display_string(int x, int y, const char *str) {
    // Simple character mapping (ASCII 32-126) to 5x7 font
    // This is a placeholder; a real implementation would require a font table
    // and more complex rendering logic.

