    for (int i = 0; str[i] != '\0'; i++) {
        // Simple block pattern (5 pixels wide, 7 pixels tall)
        for (int j = 0; j < 5; j++) {
            ssd1306_data(0xFF); // Set all bits to 1 for a block
        }
