    }
}

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temperature = 0.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Failed to open CPU temperature file");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    }

    fclose(fp);
    return temperature;
}

