#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3, *line_5;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO pin state
int set_gpio_state(struct gpiod_line *line, int value);

// Function to report the state of GPIO pins
void report_state(int state_2, int state_3, int state_5);

int main() {
    int state_2, state_3, state_5;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    line_5 = gpiod_chip_get_line(chip, GPIO_5);
    if (!line_2 || !line_3 || !line_5) {
        fprintf(stderr, "Error: Could not get GPIO line for GPIO %d, %d, or %d\n", GPIO_2, GPIO_3, GPIO_5);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_2, "my_subsystem", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output\n", GPIO_2);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_3, "my_subsystem", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output\n", GPIO_3);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_5, "my_subsystem", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output\n", GPIO_5);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        set_gpio_state(line_2, 1);
        set_gpio_state(line_3, 0);
        set_gpio_state(line_5, 1);

        // Report GPIO states
        report_state(1, 0, 1);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_2) gpiod_line_release(line_2);
    if (line_3) gpiod_line_release(line_3);
    if (line_5) gpiod_line_release(line_5);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

// Function to set GPIO pin state
int set_gpio_state(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO state\n");
        return 1;
    }
    return 0;
}

// Function to report the state of GPIO pins
void report_state(int state_2, int state_3, int state_5) {
    printf("GPIO 2: %d, GPIO 3: %d, GPIO 5: %d\n", state_2, state_3, state_5);
}

