#define ECHO_PIN 23
#define ECHO2_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MAX_DISTANCE 400      // cm
#define TIMEOUT 100000         // us

// Global variables
static volatile int terminate = 0;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo2_start_tick = 0;
static volatile int echo2_end_tick = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1)
        {
            echo_start_tick = tick;
        }
        else if (level == 0)
        {
            echo_end_tick = tick;
        }
    }
    else if (gpio == ECHO2_PIN)
    {
        if (level == 1)
        {
            echo2_start_tick = tick;
        }
        else if (level == 0)
        {
            echo2_end_tick = tick;
        }
    }
}

// Function to measure distance
float measure_distance(int trig_pin, int echo_pin)
{
    echo_start_tick = 0;
    echo_end_tick = 0;

    gpioWrite(trig_pin, 0);
    gpioDelay(2);
    gpioWrite(trig_pin, 1);
    gpioDelay(10);
    gpioWrite(trig_pin, 0);

    // Wait for echo or timeout
    int timeout_count = 0;
    while (echo_start_tick == 0 && timeout_count < TIMEOUT)
    {
        gpioDelay(1);
        timeout_count++;
    }

    if (echo_start_tick == 0)
    {
        return -1; // Timeout
    }

    timeout_count = 0;
    while (echo_end_tick == 0 && timeout_count < TIMEOUT)
    {
        gpioDelay(1);
        timeout_count++;
    }

    if (echo_end_tick == 0)
    {
        return -1; // Timeout
    }

    // Calculate pulse width
    int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance
    float distance = (pulse_width * SPEED_OF_SOUND) / 2.0;

    return distance;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(ECHO2_PIN, PI_INPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(ECHO2_PIN, PI_PUD_DOWN);

    // Set callback functions
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);
    gpioSetAlertFuncEx(ECHO2_PIN, echo_callback, NULL);

    // Register signal handler
    signal(SIGINT, signal_handler);

