            fprintf(stderr, "Error: Could not set GPIO value: %d\n", ret);
            break;
        }

        // Wait 50ms
        usleep(50000);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

