}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit
    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[7];
    data[0] = ACCEL_XOUT_H;

    if (write(fd, data, 1) != 1) {
        perror("Error writing to ACCEL_XOUT_H");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    struct timespec ts;
    char timestamp[30];

    // Read and print accelerometer data 100 times
    for (int i = 0; i < 100; i++) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            printf("%s.%09ld, %d, %d, %d\n", timestamp, ts.tv_nsec, x, y, z);
        } else {
            fprintf(stderr, "Error reading accelerometer data. Exiting.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 14
#define GPIO_PIN_2 15

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int value1, value2;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN_1);
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN_2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line1, "my_label", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_PIN_1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "my_label", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_PIN_2);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 14 to 1, GPIO 15 to 0
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value\n", GPIO_PIN_1);
            break;
        }

        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value\n", GPIO_PIN_2);
            break;
        }

        // Read back the values (for validation)
        value1 = gpiod_line_get_value(line1);
        if (value1 < 0) {
            fprintf(stderr, "Error reading GPIO %d value\n", GPIO_PIN_1);
            break;
        }
        if (value1 != 1) {
            fprintf(stderr, "Invalid value read from GPIO %d: %d\n", GPIO_PIN_1, value1);
            break;
        }

        value2 = gpiod_line_get_value(line2);
        if (value2 < 0) {
            fprintf(stderr, "Error reading GPIO %d value\n", GPIO_PIN_2);
            break;
        }
        if (value2 != 0) {
            fprintf(stderr, "Invalid value read from GPIO %d: %d\n", GPIO_PIN_2, value2);
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, value1, GPIO_PIN_2, value2);

        sleep(5);
    }

    // Release GPIO lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
