#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "environmental_data"
#define SENSOR_ID "RPi_Sensor_1"
#define READ_INTERVAL_MS 10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int signum);
int read_sensor_data(float *temperature, float *humidity);
int publish_data(float temperature, float humidity);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting gracefully...\n");
        running = 0;
    }
}

// Function to read sensor data (simulated)
int read_sensor_data(float *temperature, float *humidity) {
    // Simulate reading from a sensor
    // Replace this with actual sensor reading code using pigpio
    static int call_count = 0;
    call_count++;

    if (call_count % 5 == 0) {
        // Simulate an error every 5th call
        return -1; // Indicate an error
    }

    // Generate some random values
    *temperature = 20.0 + (rand() % 100) / 10.0; // Temperature between 20.0 and 30.0
    *humidity = 50.0 + (rand() % 500) / 10.0;    // Humidity between 50.0 and 100.0

    return 0; // Indicate success
}

// Function to publish data to MQTT broker
int publish_data(float temperature, float humidity) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"sensor_id\": \"%s\", \"temperature\": %.2f, \"humidity\": %.2f}", SENSOR_ID, temperature, humidity);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Callback function for MQTT connection
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
    } else {
        fprintf(stderr, "Connection error: %s\n", mosquitto_connack_string(result));
    }
}

// Callback function for MQTT disconnection
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        fprintf(stderr, "Disconnected unexpectedly with code %d\n", rc);
    }
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    int ret = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int retries;

    // Main loop
    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(&temperature, &humidity) == 0) {
                // Validity check
                if (temperature >= -20.0 && temperature <= 60.0 && humidity >= 0.0 && humidity <= 100.0) {
                    if (publish_data(temperature, humidity) == 0) {
                        // Data published successfully
                        break; // Exit retry loop
                    } else {
                        fprintf(stderr, "Failed to publish data, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Invalid sensor data, rejecting reading.\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data, retrying...\n");
            }

            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000); // Delay before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries, skipping.\n", MAX_RETRIES);
        }

        usleep(READ_INTERVAL_MS * 1000); // Delay between readings
    }

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

