//define the pin connected to the echo
#define ECHO_PIN     22
//define the pin connected to the enable
#define ENABLE_PIN   27

//define the speed of sound
#define SOUND_SPEED  0.0343
//define the distance range
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2

//function to measure the distance
float getDistance()
{
    long startTime, endTime, pulseWidth;
    float distance;
    //set the trigger pin to low
    digitalWrite(TRIGGER_PIN, LOW);
    //delay 2us
    delayMicroseconds(2);
    //set the trigger pin to high
    digitalWrite(TRIGGER_PIN, HIGH);
    //delay 10us
    delayMicroseconds(10);
    //set the trigger pin to low
    digitalWrite(TRIGGER_PIN, LOW);
    //clear the echo pin
    pinMode(ECHO_PIN, INPUT);
    //get the start time
    startTime = micros();
    //wait for the echo pin to go high
    while (digitalRead(ECHO_PIN) == LOW)
    {
        //get the current time
        endTime = micros();
        //if the time difference is greater than 250ms, return -1
        if (endTime - startTime > 250000)
        {
            return -1;
        }
    }
    //get the end time
    startTime = micros();
    //wait for the echo pin to go low
    while (digitalRead(ECHO_PIN) == HIGH)
    {
        //get the current time
        endTime = micros();
        //if the time difference is greater than 250ms, return -1
        if (endTime - startTime > 250000)
        {
            return -1;
        }
    }
    endTime = micros();
    //calculate the pulse width
    pulseWidth = endTime - startTime;
    //calculate the distance
    distance = (pulseWidth * SOUND_SPEED) / 2;
    //return the distance
    return distance;
}

