#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <mosquitto.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define MQTT_HOST "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "wearable/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel to read
#define ADC_MAX_VALUE 1023.0 // Maximum ADC value (10-bit ADC)

// Global variables
static volatile int keepRunning = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
void signal_handler(int sig);
int mqtt_connect_and_publish(float temperature, float humidity);
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received, exiting...\n");
    keepRunning = 0;
}

// Function to connect to MQTT broker and publish data
int mqtt_connect_and_publish(float temperature, float humidity) {
    int rc;

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(MQTT_TOPIC), MQTT_TOPIC, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(rc));
        return 1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    wiringPiSPIClose(SPI_CHANNEL);
    wiringPiSetup(); // Reset wiringPi
    printf("Cleanup complete.\n");
}

int main() {
    int rc;
    float temperature, humidity;
    int adc_value;

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    // Set MQTT keepalive interval
    mosquitto_setopt(mosq, MOSQ_OPT_KEEPALIVE, 60);

    // Set MQTT last will message
    mosquitto_will_set(mosq, MQTT_TOPIC, strlen(MQTT_TOPIC), MQTT_TOPIC, 0, false);

    // Connect to MQTT broker
    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Publishing sensor data to %s\n", MQTT_TOPIC);

    while (keepRunning) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Convert ADC value to temperature (example: 25°C + (ADC_value / 1023) * 50°C)
        temperature = 25.0 + (float)adc_value / ADC_MAX_VALUE * 50.0;

        // Convert ADC value to humidity (example: 50% + (ADC_value / 1023) * 50%)
        humidity = 50.0 + (float)adc_value / ADC_MAX_VALUE * 50.0;

        // Publish data to MQTT broker
        if (mqtt_connect_and_publish(temperature, humidity) != 0) {
            fprintf(stderr, "Error publishing data.\n");
        }

        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);

        sleep(5);
    }

    // Disconnect and cleanup
    cleanup();

    return 0;
}

#include <stdio.h>
