#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

int main() {
    int i, duty_cycle;
    FILE *fp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode to output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open standard output for logging
    fp = stdout;

    // Main loop
    while (!terminate) {
        // Set duty cycle
        for (i = 0; i < 100; i++) {
            duty_cycle = i;
            gpioPWM(PWM_GPIO, duty_cycle);
            fprintf(fp, "PWM: %d\n", duty_cycle);
            fflush(fp);
            sleep(5);
        }

        // Reverse duty cycle
        for (i = 99; i >= 0; i--) {
            duty_cycle = i;
            gpioPWM(PWM_GPIO, duty_cycle);
            fprintf(fp, "PWM: %d\n", duty_cycle);
            fflush(fp);
            sleep(5);
        }
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

