#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN  23
#define ECHO_PIN  24

// Define speed of sound
#define SPEED_OF_SOUND 34300.0 // cm/s

// Define timeout
#define TIMEOUT 100000 // us

// Global variables
static volatile int terminate = 0;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed, exiting...\n");
    terminate = 1;
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            echo_start_tick = tick;
        }
        else if (level == 0) // Falling edge
        {
            echo_end_tick = tick;

            // Calculate pulse width
            int32_t pulse_width = echo_end_tick - echo_start_tick;

            // Check for timeout
            if (pulse_width > TIMEOUT)
            {
                printf("Timeout\n");
                return;
            }

            // Calculate distance
            float distance = (float)(pulse_width / 2.0) * (SPEED_OF_SOUND / 1000000.0);

            // Print distance
            printf("Distance: %.2f cm\n", distance);
        }
    }
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor for echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (!terminate)
    {
        // Trigger sensor
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIG_PIN, 0);

        // Wait for 0.2 seconds
        gpioDelay(200000); // 200 ms
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

