#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <mosquitto.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define MQTT_HOST "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "wearable/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel to read
#define SAMPLE_INTERVAL_MS 1000 // Sample every 1 second

// Global variables
static volatile int keepRunning = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
int validate_reading(int reading);
void signal_handler(int sig);
int mqtt_connect_and_publish(int reading);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keepRunning = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to validate sensor reading
int validate_reading(int reading) {
    if (reading >= 0 && reading <= 1023) {
        return 1; // Valid reading
    } else {
        return 0; // Invalid reading
    }
}

// Function to connect to MQTT broker and publish data
int mqtt_connect_and_publish(int reading) {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    char payload[20];
    snprintf(payload, sizeof(payload), "%d", reading);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not publish message: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    return 0;
}

int main() {
    int reading;

    // Setup signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error: Unable to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error: Unable to initialize SPI: %s\n", strerror(errno));
        return 1;
    }

    printf("Starting sensor data publication...\n");

    while (keepRunning) {
        // Read sensor data
        reading = read_mcp3008(MCP3008_CHANNEL);

        // Validate reading
        if (validate_reading(reading)) {
            // Publish data to MQTT broker
            if (mqtt_connect_and_publish(reading) != 0) {
                fprintf(stderr, "Error: Failed to publish data.\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid sensor reading: %d\n", reading);
        }

        // Wait for the next sample
        delay(SAMPLE_INTERVAL_MS);
    }

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <mosquitto.h>

// Configuration
#define I2C_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "environmental_data"
#define NUM_READINGS 10

// Global variables
static volatile int keepRunning = 1;
static int i2c_fd;
static struct mosquitto *mosq = NULL;

// Function prototypes
int init_i2c();
int init_mqtt();
void read_sensor_data(int *reading);
void publish_data(int reading);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    keepRunning = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Configure ADS1115 for single-ended input A0, +/-4.096V, continuous conversion mode
    int config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    if (wiringPiI2CWriteReg16(i2c_fd, CONFIG_REG, config) == -1) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Initialize MQTT client
int init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating Mosquitto client.\n");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error starting MQTT loop: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Read sensor data
void read_sensor_data(int *reading) {
    int16_t raw_value = wiringPiI2CReadReg16(i2c_fd, CONVERSION_REG);
    if (raw_value == -1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        *reading = -1; // Indicate error
        return;
    }

    // Convert raw value to voltage
    *reading = (int)(raw_value * REF_VOLTAGE / 32768.0);
}

// Publish data to MQTT broker
void publish_data(int reading) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"temperature\": %d, \"humidity\": %d}", reading, reading);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(rc));
    }
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources.\n");
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    if (i2c_fd != -1) {
        // No specific I2C cleanup function in wiringPi, but we can close the file descriptor.
        // close(i2c_fd); // Not needed with wiringPiI2C
    }
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() == -1) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int readings[NUM_READINGS];
    int i;

    // Take sensor readings and publish data
    for (i = 0; i < NUM_READINGS && keepRunning; i++) {
        read_sensor_data(&readings[i]);
        if (readings[i] != -1) {
            publish_data(readings[i]);
            printf("Published reading: %d\n", readings[i]);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        delay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

