#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit
    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[7];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (program_running) {
        int16_t x, y, z;

        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Print accelerometer data
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }

        usleep(100000); // 0.1 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the BMP280
int read_register(int fd, uint8_t reg_addr) {
    int result = i2c_smbus_read_byte_data(fd, reg_addr);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to the BMP280
int write_register(int fd, uint8_t reg_addr, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg_addr, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    calib->dig_T1 = (uint16_t)read_register(fd, BMP280_REG_CALIB_00); //0x88
    calib->dig_T1 |= ((uint16_t)read_register(fd, BMP280_REG_CALIB_00 + 1) << 8); //0x89
    calib->dig_T2 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 2); //0x8A
    calib->dig_T2 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 3) << 8); //0x8B
    calib->dig_T3 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 4); //0x8C
    calib->dig_T3 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 5) << 8); //0x8D
    calib->dig_P1 = (uint16_t)read_register(fd, BMP280_REG_CALIB_00 + 6); //0x8E
    calib->dig_P1 |= ((uint16_t)read_register(fd, BMP280_REG_CALIB_00 + 7) << 8); //0x8F
    calib->dig_P2 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 8); //0x90
    calib->dig_P2 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 9) << 8); //0x91
    calib->dig_P3 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 10); //0x92
    calib->dig_P3 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 11) << 8); //0x93
    calib->dig_P4 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 12); //0x94
    calib->dig_P4 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 13) << 8); //0x95
    calib->dig_P5 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 14); //0x96
    calib->dig_P5 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 15) << 8); //0x97
    calib->dig_P6 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 16); //0x98
    calib->dig_P6 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 17) << 8); //0x99
    calib->dig_P7 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 18); //0x9A
    calib->dig_P7 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 19) << 8); //0x9B
    calib->dig_P8 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 20); //0x9C
    calib->dig_P8 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 21) << 8); //0x9D
    calib->dig_P9 = (int16_t)read_register(fd, BMP280_REG_CALIB_00 + 22); //0x9E
    calib->dig_P9 |= ((int16_t)read_register(fd, BMP280_REG_CALIB_00 + 23) << 8); //0x9F

    return 0;
}

// Function to read temperature and pressure from the BMP280
int read_bmp280(int fd, float *temperature, float *pressure) {
    // Set the BMP280 to forced mode
    if (write_register(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error setting forced mode.\n");
        return -1;
    }

    // Wait for the measurement to complete (datasheet recommends at least 2ms)
    usleep(5000); // 5ms

    // Read the raw temperature and pressure values
    int32_t raw_temp = ((int32_t)read_register(fd, BMP280_REG_TEMP_MSB) << 12) |
                       ((int32_t)read_register(fd, BMP280_REG_TEMP_LSB) << 4) |
                       ((int32_t)read_register(fd, BMP280_REG_TEMP_XLSB) >> 4);

    int32_t raw_press = ((int32_t)read_register(fd, BMP280_REG_PRESS_MSB) << 12) |
                        ((int32_t)read_register(fd, BMP280_REG_PRESS_LSB) << 4) |
                        ((int32_t)read_register(fd, BMP280_REG_PRESS_XLSB) >> 4);

    // Temperature compensation
    double var1 = (raw_temp / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temp / 131072.0 - calib.dig_T1 / 8192.0) *
                   (raw_temp / 131072.0 - calib.dig_T1 / 8192.0)) *
                  calib.dig_T3;
    double t_fine = var1 + var2;
    *temperature = (t_fine / 5120.0);

    // Pressure compensation
    double var3 = t_fine / 2.0 - 64000.0;
    double var4 = var3 * var3 * calib.dig_P6 / 32768.0;
    double var5 = var4 + var3 * calib.dig_P5 * 2.0;
    double var6 = var5 / 4.0 + calib.dig_P4 * 65536.0;
    double var7 = calib.dig_P3 * var3 * var3 / 524288.0;
    double var8 = calib.dig_P2 * var3 / 524288.0;
    double var9 = (1.0 + var7 + var8) * calib.dig_P1;
    double p = 1048576.0 - raw_press;
    p = (p - var6 / 4096.0) * 6250.0 / var9;
    var3 = calib.dig_P9 * p * p / 2147483648.0;
    var4 = p * calib.dig_P8 / 32768.0;
    *pressure = (p + (var3 + var4 + calib.dig_P7) / 16.0) / 100.0; // in hPa

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check the BMP280 ID register
    int chip_id = read_register(i2c_fd, BMP280_REG_ID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X. Expected 0x58.\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) < 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature, pressure;

        if (read_bmp280(i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading BMP280 data.\n");
        }

        sleep(5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
