#define PWM_GPIO 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

int main() {
    int i, result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode to output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to %d.  Got %d\n", PWM_FREQUENCY, result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Main loop
    for (i = 0; i < PWM_RANGE && !terminate; i++) {
        gpioPWM(PWM_GPIO, i);
        printf("PWM: %d\n", i);
        usleep(10000); // 10ms delay
    }

    // Stop PWM
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

