// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "wearable/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel to read

// Global variables
static struct mosquitto *mosq = NULL;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void signal_handler(int signum);
int mqtt_connect_and_subscribe(void);
void mqtt_disconnect(void);
void publish_sensor_data(int sensor_value);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    terminate = 1;
    printf("\nSignal received, cleaning up...\n");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// MQTT connect and subscribe function
int mqtt_connect_and_subscribe(void) {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not start MQTT loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    printf("Connected to MQTT broker and subscribed to topic: %s\n", MQTT_TOPIC);
    return 0;
}

// MQTT disconnect function
void mqtt_disconnect(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    printf("Disconnected from MQTT broker.\n");
}

// Function to publish sensor data to MQTT broker
void publish_sensor_data(int sensor_value) {
    time_t now = time(NULL);
    char payload[50];
    int rc;

    snprintf(payload, sizeof(payload), "{\"timestamp\":%ld, \"value\":%d}", now, sensor_value);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not publish message: %s\n", mosquitto_strerror(rc));
    } else {
        printf("Published sensor data: %s\n", payload);
    }
}

int main(void) {
    int sensor_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Connect to MQTT broker and subscribe to topic
    if (mqtt_connect_and_subscribe() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor value from MCP3008
        sensor_value = read_mcp3008(MCP3008_CHANNEL);
        if (sensor_value >= 0) {
            // Publish sensor data to MQTT broker
            publish_sensor_data(sensor_value);
        } else {
            fprintf(stderr, "Error: Failed to read sensor value\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    spiClose(spi_handle);
    gpioTerminate();
    mqtt_disconnect();

    return 0;
}

