/*
 * serialSetup:
 *	Set up the serial port
 *********************************************************************************
 */

int serialSetup (int fd, int port, int speed)
{
  int fd2, fd3, fd4 ;
  struct termios tty ;

  serialFD = fd ;
  serialPort = port ;
  serialSpeed = speed ;

  if ((fd2 = open ("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY)) != -1)
  {
    close (fd2) ;
  }

  if ((fd3 = open ("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY)) != -1)
  {
    close (fd3) ;
  }

  if ((fd4 = open ("/dev/ttyS1", O_RDWR | O_NOCTTY | O_NDELAY)) != -1)
  {
    close (fd4) ;
  }

  if ((serialFile = open ("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY)) == -1)
  {
    perror ("open(/dev/ttyS0)");
    exit (1) ;
  }

  if ((serialFile2 = open ("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY)) == -1)
  {
    perror ("open(/dev/ttyAMA0)");
    exit (1) ;
  }

  if ((serialFile3 = open ("/dev/ttyS1", O_RDWR | O_NOCTTY | O_NDELAY)) == -1)
  {
    perror ("open(/dev/ttyS1)");
    exit (1) ;
  }

  if ((serialFile4 = open ("/dev/ttySAC0", O_RDWR | O_NOCTTY | O_NDELAY)) == -1)
  {
    perror ("open(/dev/ttySAC0)");
    exit (1) ;
  }

  if (tcgetattr (serialFile, &tty) != 0)
  {
    perror ("tcgetattr") ;
    exit (1) ;
  }

  cfsetospeed (&tty, speed) ;
  cfsetispeed (&tty, speed) ;

  tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8 ;     // 8-bit chars
  tty.c_iflag &= ~IGNBRK;         // disable break processing
  tty.c_lflag = 0;                // no signaling chars, no echo,
                                  // no canonical processing
  tty.c_oflag = 0;                // no remapping, no delays
  tty.c_cc[VMIN]  = 0;            // read doesn't block
  tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

  tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

  tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
  tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
  tty.c_cflag &= ~CSTOPB;
  tty.c_cflag &= ~CRTSCTS;

  if (tcsetattr (serialFile, TCSANOW, &tty) != 0)
  {
    perror ("tcsetattr") ;
    exit (1) ;
  }

  return fd ;
}


/*
 * serialRead:
 *	Read from the serial port
 *********************************************************************************
 */

int serialRead (int fd, char *buf, int len)
{
  int i = 0 ;
  int c ;

  while (i < len)
  {
    c = read (fd, buf + i, 1) ;
    if (c < 0)
    {
      if (errno == EAGAIN) continue ;
      perror ("read") ;
      return -1 ;
    }
    if (c == 0) break ;
    i++ ;
  }
  return i ;
}


/*
 * serialWrite:
 *	Write to the serial port
 *********************************************************************************
 */

