#define DHT22_GPIO 4
#define MAX_TIMINGS 85

static volatile int data[5] = {0, 0, 0, 0, 0};
static volatile int laststate = PI_HIGH;
static volatile int j = 0;
static volatile int reading_active = 0;
static volatile int terminate = 0;

void signal_handler(int signal) {
    printf("Caught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

void dht22_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (diff > 200) return; // Ignore spurious signals

    if (level == PI_LOW) {
        if (laststate == PI_HIGH) {
            data[j / 8] <<= 1;
            if (diff > 50) {
                data[j / 8] |= 1;
            }
            laststate = PI_LOW;
            j++;
        }
    } else {
        laststate = PI_HIGH;
    }

    last_tick = tick;

    if (j >= MAX_TIMINGS) {
        reading_active = 0; // Signal end of reading
    }
}

int read_dht22(int gpio) {
    int result = 0;
    int i;

    if (gpioSetMode(gpio, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", gpio);
        return -1;
    }

    if (gpioSetPullUpDown(gpio, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO %d pull-up resistor\n", gpio);
        return -1;
    }

    j = 0;
    laststate = PI_HIGH;
    reading_active = 1;

    while (reading_active) {
        gpioDelay(1); // Small delay to allow signal to propagate
    }

    if (j < MAX_TIMINGS) {
        fprintf(stderr, "Error: Not enough data received (%d)\n", j);
        return -1;
    }

    // Checksum validation
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Error: Checksum validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    float humidity = (float)data[0] + (float)data[1] / 10.0;
    float temperature = (float)data[2] + (float)data[3] / 10.0;

    printf("Humidity: %.1f%%, Temperature: %.1f°C\n", humidity, temperature);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetAlertFuncEx(DHT22_GPIO, dht22_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        gpioTerminate();
        return 1;
    }

    if (read_dht22(DHT22_GPIO) != 0) {
        fprintf(stderr, "DHT22 read failed\n");
        gpioTerminate();
        return 1;
    }

    gpioTerminate();
    return 0;
}

