#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // Channel to read from MCP3008
#define MQTT_HOST "localhost" // MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "environmental_data"
#define MQTT_CLIENT_ID "rpi_mcp3008_sensor"

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void signal_handler(int sig);
int mqtt_connect_and_subscribe(void);
void mqtt_disconnect(void);
void publish_data(int adc_value);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// MQTT connect and subscribe function
int mqtt_connect_and_subscribe(void) {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    return 0;
}

// MQTT disconnect function
void mqtt_disconnect(void) {
    int rc = mosquitto_disconnect(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error disconnecting: %s\n", mosquitto_strerror(rc));
    }
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

// Function to publish data to MQTT broker
void publish_data(int adc_value) {
    char payload[20];
    int rc;

    snprintf(payload, sizeof(payload), "%d", adc_value);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing: %s\n", mosquitto_strerror(rc));
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT
    if (mqtt_connect_and_subscribe() != 0) {
        fprintf(stderr, "MQTT initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            publish_data(adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(1); // Publish every 1 second
    }

    // Cleanup
    mqtt_disconnect();
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <unistd.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
        void   *start;
        size_t  length;
};

static int fd = -1;
static struct buffer *buffers = NULL;
static unsigned int n_buffers = 0;

static int xioctl(int fh, int request, void *arg)
{
        int r;

        do {
                r = ioctl(fh, request, arg);
        } while (-1 == r && EINTR == errno);

        return r;
}

int main(int argc, char **argv)
{
        const char *dev_name = "/dev/video0";
        struct v4l2_capability cap;
        struct v4l2_format fmt;
        struct v4l2_requestbuffers req;
        unsigned int i;
        enum v4l2_buf_type type;
        struct v4l2_streamparm streamparm;
        struct v4l2_fract fract;
        struct v4l2_streamparm new_streamparm;
        struct v4l2_format new_fmt;

        int fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);

        if (fd < 0) {
                perror("Cannot open device");
                exit(1);
        }

        if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
                perror("VIDIOC_QUERYCAP");
                close(fd);
                exit(1);
        }

        if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
                fprintf(stderr, "%s is no video capture device\n", dev_name);
                close(fd);
                exit(1);
        }

        if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
                fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
                close(fd);
                exit(1);
        }

        CLEAR(fmt);

        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = 640;
        fmt.fmt.pix.height = 480;
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
        fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

        if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
                perror("VIDIOC_S_FMT");
                close(fd);
                exit(1);
        }

        CLEAR(req);

        req.count = 4; // Number of buffers
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
                perror("VIDIOC_REQBUFS");
                close(fd);
                exit(1);
        }

        buffers = calloc(req.count, sizeof(*buffers));

        if (!buffers) {
                fprintf(stderr, "Out of memory\n");
                close(fd);
                exit(1);
        }

        for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
                struct v4l2_buffer buf;

                CLEAR(buf);

                buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory      = V4L2_MEMORY_MMAP;
                buf.index       = n_buffers;

                if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
                        perror("VIDIOC_QUERYBUF");
                        close(fd);
                        exit(1);
                }

                buffers[n_buffers].length = buf.length;
                buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

                if (MAP_FAILED == buffers[n_buffers].start) {
                        perror("mmap");
                        close(fd);
                        exit(1);
                }
        }

        for (i = 0; i < n_buffers; ++i) {
                struct v4l2_buffer buf;

                CLEAR(buf);

                buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory      = V4L2_MEMORY_MMAP;
                buf.index       = i;

                if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                        perror("VIDIOC_QBUF");
                        close(fd);
                        exit(1);
                }
        }

        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

        if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
                perror("VIDIOC_STREAMON");
                close(fd);
                exit(1);
        }

        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                close(fd);
                exit(1);
        }

        FILE *fp = fopen("image.mjpg", "wb");
        if (!fp) {
                perror("fopen");
                close(fd);
                exit(1);
        }

        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                close(fd);
                exit(1);
        }

        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
                perror("VIDIOC_STREAMOFF");
                close(fd);
                exit(1);
        }

        for (i = 0; i < n_buffers; ++i) {
                munmap(buffers[i].start, buffers[i].length);
        }

        free(buffers);

        close(fd);

        return 0;
}

