#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define timeout duration (in milliseconds)
#define TIMEOUT_MS 50

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int init_gpio(void);

// Function to trigger the HC-SR04 sensor
int trigger_sensor(void);

// Function to read the echo pin state with timeout
int read_echo(void);

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width);

// Function to cleanup GPIO resources
void cleanup_gpio(void);

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error triggering sensor.\n");
            cleanup_gpio();
            return 1;
        }

        // Read the echo pin state with timeout
        int pulse_width = read_echo();

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d. Cleaning up and exiting.\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int init_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line for output
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line for input
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line for input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to trigger the HC-SR04 sensor
int trigger_sensor(void) {
    // Set trigger pin high
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger pin high");
        return -1;
    }

    // Wait for 10 microseconds
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000; // 10 microseconds
    nanosleep(&ts, NULL);

    // Set trigger pin low
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger pin low");
        return -1;
    }

    return 0;
}

// Function to read the echo pin state with timeout
int read_echo(void) {
    struct timespec start, end;
    int pulse_width = 0;

    // Wait for echo pin to go high with timeout
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000L + (now.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_MS * 1000000) {
            fprintf(stderr, "Timeout waiting for echo high.\n");
            return -1; // Timeout
        }
    }

    // Measure pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000L + (now.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_MS * 1000000) {
            fprintf(stderr, "Timeout waiting for echo low.\n");
            return -1; // Timeout
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width) {
    return (pulse_width * 0.0343) / 2.0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

