    if (-1 == xioctl(fd, VIDIOC_DQBUF, &v4l2_buf)) {
        syslog(LOG_ERR, "VIDIOC_DQBUF error: %s", strerror(errno));
        return -1;
    }

    buf->length = v4l2_buf.bytesused;
    buf->start = v4l2_buf.m.offset;

    if (-1 == xioctl(fd, VIDIOC_QBUF, &v4l2_buf)) {
        syslog(LOG_ERR, "VIDIOC_QBUF error: %s", strerror(errno));
