static int capture_image(int fd, const char *filename)
{
    struct v4l2_format fmt;
    struct v4l2_streamparm streamparm;
    struct v4l2_requestbuffers req;
    unsigned int i;

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;  // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        syslog(LOG_ERR, "VIDIOC_S_FMT error: %s", strerror(errno));
        return -1;
    }

    CLEAR(streamparm);
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 1;
    streamparm.parm.capture.timeperframe.denominator = 30; // 30fps

    if (-1 == xioctl(fd, VIDIOC_S_PARM, &streamparm)) {
        syslog(LOG_ERR, "VIDIOC_S_PARM error: %s", strerror(errno));
        return -1;
    }

    CLEAR(req);
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        syslog(LOG_ERR, "VIDIOC_REQBUFS error: %s", strerror(errno));
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        syslog(LOG_ERR, "Out of memory");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            syslog(LOG_ERR, "VIDIOC_QUERYBUF error: %s", strerror(errno));
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            syslog(LOG_ERR, "mmap error: %s", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        syslog(LOG_ERR, "VIDIOC_STREAMON error: %s", strerror(errno));
        return -1;
    }

    for (i = 0; i < 10 && !stop_flag; ++i) {
        if (read_frame(fd, &buffers[i % n_buffers]) < 0) {
            syslog(LOG_ERR, "Failed to read frame %d", i);
            break;
        }
    }

    enum v4l2_buf_type type2 = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type2)) {
        syslog(LOG_ERR, "VIDIOC_STREAMOFF error: %s", strerror(errno));
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open file for writing: %s", strerror(errno));
        return -1;
    }

    for (i = 0; i < 10 && !stop_flag; ++i) {
        if (buffers[i % n_buffers].length > 0) {
            fwrite(buffers[i % n_buffers].start, 1, buffers[i % n_buffers].length, fp);
        }
    }

    fclose(fp);

    return 0;
}

int main(int argc, char **argv)
{
    const char *dev_name = "/dev/video0";
    const char *filename = "image.jpg";
    int i;

    openlog("image_capture", LOG_PID, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Cannot open '%s': %s", dev_name, strerror(errno));
        return EXIT_FAILURE;
    }

