        syslog(LOG_ERR, "Failed to capture image");
        close(fd);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Image captured and saved to %s", filename);

    close(fd);
    munmap(buffers[0].start, buffers[0].length);
    free(buffers);
    closelog();

    return EXIT_SUCCESS;
}

