#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define PCF8574_ADDR 0x20      // PCF8574 I2C address
#define DISPLAY_WIDTH 16        // Display width in characters

// Global variables
int i2c_fd;                   // I2C file descriptor
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_setup(const char *bus, int addr);
int pcf8574_write(int fd, unsigned char data);
void display_message(int fd, const char *message);
void cleanup(int fd);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        program_running = 0; // Set the flag to exit the main loop
    }
}

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// PCF8574 write function
int pcf8574_write(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Display message function
void display_message(int fd, const char *message) {
    int i, j;
    unsigned char data = 0;

    for (i = 0; i < DISPLAY_WIDTH; i++) {
        for (j = 0; j < 8; j++) {
            if (message[i] & (1 << (7 - j))) {
                data |= (1 << j); // Set bit if character has a '1' at that position
            }
        }
        if (pcf8574_write(fd, data) < 0) {
            fprintf(stderr, "Error writing to display at position %d\n", i);
        }
    }
}

// Cleanup function
void cleanup(int fd) {
    close(fd);
    printf("I2C bus closed.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error setting signal handler");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, PCF8574_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // Display a message
    display_message(i2c_fd, "Hello, Pi!");

    // Cleanup and exit
    cleanup(i2c_fd);
    return 0;
}

