#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int start_tick, int end_tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 2; // Indicate that the falling edge has been received
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int start_tick, int end_tick) {
    double diff = (double)(end_tick - start_tick);
    double distance = (diff / 1000000.0) * SPEED_OF_SOUND / 2.0; // Divide by 2 because of the round trip
    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        trigger_pulse();
        echo_start_tick = 0; // Reset start tick
        echo_end_tick = 0;   // Reset end tick
        echo_received = 0;    // Reset received flag

        // Wait for echo pulse with timeout
        int timeout = 0;
        while (echo_received != 2 && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout++;
        }

        if (echo_received != 2) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        double distance = calculate_distance(echo_start_tick, echo_end_tick);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Delay before next measurement
        gpioDelay(200000); // 200ms delay
    }

    // Cleanup (this part will not be reached in the infinite loop)
    gpioTerminate();
    return 0;
}

