#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (set power management register to 0)
    uint8_t data[2];
    data[0] = MPU6050_PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit
    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the MPU6050
int16_t read_mpu6050_value(int fd, uint8_t reg) {
    uint8_t data[1];
    data[0] = reg;
    if (write(fd, data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read accelerometer and gyroscope data
        int16_t accel_x = read_mpu6050_value(i2c_fd, MPU6050_ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6050_value(i2c_fd, MPU6050_ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6050_value(i2c_fd, MPU6050_ACCEL_XOUT_H + 4);
        int16_t gyro_x = read_mpu6050_value(i2c_fd, MPU6050_GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6050_value(i2c_fd, MPU6050_GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6050_value(i2c_fd, MPU6050_GYRO_XOUT_H + 4);

        // Print the data
        if (accel_x != -1 && accel_y != -1 && accel_z != -1 && gyro_x != -1 && gyro_y != -1 && gyro_z != -1) {
            printf("AccelX: %d, AccelY: %d, AccelZ: %d, GyroX: %d, GyroY: %d, GyroZ: %d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

