#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SHT31 I2C address
#define SHT31_ADDR 0x44

// Measurement command (High Repeatability, Clock Stretching disabled)
#define MEASURE_CMD 0x2C06

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read data from SHT31
int read_sht31(float *temperature, float *humidity) {
    uint8_t write_data[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t read_data[6];
    struct timespec delay = {0, 10000000}; // 10 ms delay

    // Send measurement command
    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement to complete (typical conversion time is 10ms)
    nanosleep(&delay, NULL);

    // Read 6 bytes of data (Temp MSB, Temp LSB, Temp CRC, Hum MSB, Hum LSB, Hum CRC)
    if (read(i2c_fd, read_data, 6) != 6) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Convert data
    int temp_raw = (read_data[0] << 8) | read_data[1];
    int hum_raw = (read_data[3] << 8) | read_data[4];

    // Calculate temperature (Celsius)
    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    // Calculate humidity (%RH)
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

// Function to validate temperature and humidity readings
int validate_reading(float temperature, float humidity) {
    if (temperature < -40.0 || temperature > 125.0) {
        fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", temperature);
        return -1;
    }

    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Error: Invalid humidity reading: %.2f\n", humidity);
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    while (1) {
        // Read temperature and humidity
        if (read_sht31(&temperature, &humidity) == 0) {
            // Validate reading
            if (validate_reading(temperature, humidity) == 0) {
                // Print temperature and humidity
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error: Failed to read from SHT31\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // This point will not be reached unless there's an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

