#include <gpiod.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_22, *line_27;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO state
int set_gpio_state(struct gpiod_line *line, int value);

// Function to report GPIO state
void report_gpio_state(int gpio, int value);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_22 = gpiod_chip_get_line(chip, GPIO_22);
    line_27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line_17 || !line_22 || !line_27) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_17, "my_subsystem", 0) < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_22, "my_subsystem", 0) < 0) {
        perror("Error requesting GPIO line 22 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_27, "my_subsystem", 0) < 0) {
        perror("Error requesting GPIO line 27 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        set_gpio_state(line_17, 1);
        set_gpio_state(line_22, 0);
        set_gpio_state(line_27, 1);

        // Report GPIO states
        report_gpio_state(GPIO_17, 1);
        report_gpio_state(GPIO_22, 0);
        report_gpio_state(GPIO_27, 1);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_17) gpiod_line_release(line_17);
    if (line_22) gpiod_line_release(line_22);
    if (line_27) gpiod_line_release(line_27);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

