    printf("GPIO %d: %d\n", gpio, value);
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle)
{
    gpioPWM(gpio, duty_cycle);
}

// Function to report the state of all GPIO pins
void report_state()
{
    int duty_cycle1, duty_cycle2, duty_cycle3, duty_cycle4;

    // Read duty cycles from GPIO pins
    duty_cycle1 = gpioGetPWMdutycycle(PWM_PIN_1);
    duty_cycle2 = gpioGetPWMdutycycle(PWM_PIN_2);
    duty_cycle3 = gpioGetPWMdutycycle(PWM_PIN_3);
    duty_cycle4 = gpioGetPWMdutycycle(PWM_PIN_4);

    // Print the state to standard output
    printf("GPIO %d: %d\n", PWM_PIN_1, duty_cycle1);
    printf("GPIO %d: %d\n", PWM_PIN_2, duty_cycle2);
    printf("GPIO %d: %d\n", PWM_PIN_3, duty_cycle3);
    printf("GPIO %d: %d\n", PWM_PIN_4, duty_cycle4);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Set initial duty cycles (0-255)
    set_pwm_duty_cycle(PWM_PIN_1, 128);
    set_pwm_duty_cycle(PWM_PIN_2, 128);
    set_pwm_duty_cycle(PWM_PIN_3, 128);
    set_pwm_duty_cycle(PWM_PIN_4, 128);

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        report_state();
        sleep(1); // Report state every 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

