static int xioctl(int fh, int request, void *arg)
{
        int r;

        do {
                r = ioctl(fh, request, arg);
        } while (-1 == r && EINTR == errno);

        return r;
}

int main(int argc, char **argv)
{
        const char *dev_name = "/dev/video0";
        struct v4l2_capability cap;
        struct v4l2_format fmt;
        struct v4l2_requestbuffers req;
        unsigned int i;
        enum v4l2_buf_type type;
        struct v4l2_streamparm streamparm;
        struct v4l2_fract fract;
        struct v4l2_streamparm new_streamparm;
        struct v4l2_format new_fmt;

        int fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);

        if (fd < 0) {
                perror("Cannot open device");
                exit(EXIT_FAILURE);
        }

        if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
                perror("VIDIOC_QUERYCAP");
                close(fd);
                exit(EXIT_FAILURE);
        }

        if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
                fprintf(stderr, "%s is no video capture device\n", dev_name);
                close(fd);
                exit(EXIT_FAILURE);
        }

        if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
                fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
                close(fd);
                exit(EXIT_FAILURE);
        }

        CLEAR(fmt);

        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = 640;
        fmt.fmt.pix.height = 480;
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
        fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

        if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
                perror("VIDIOC_S_FMT");
                close(fd);
                exit(EXIT_FAILURE);
        }

        CLEAR(req);

        req.count = 4; // Number of buffers
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
                perror("VIDIOC_REQBUFS");
                close(fd);
                exit(EXIT_FAILURE);
        }

        buffers = calloc(req.count, sizeof(*buffers));

        if (!buffers) {
                fprintf(stderr, "Out of memory\n");
                close(fd);
                exit(EXIT_FAILURE);
        }

        for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
                struct v4l2_buffer buf;

                CLEAR(buf);

                buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory      = V4L2_MEMORY_MMAP;
                buf.index       = n_buffers;

                if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
                        perror("VIDIOC_QUERYBUF");
                        close(fd);
                        exit(EXIT_FAILURE);
                }

                buffers[n_buffers].length = buf.length;
                buffers[n_buffers].start = mmap(NULL, /* start anywhere */
                                                buf.length,
                                                PROT_READ | PROT_WRITE, /* required */
                                                MAP_SHARED,             /* recommended */
                                                fd, buf.m.offset);

                if (MAP_FAILED == buffers[n_buffers].start) {
                        perror("mmap");
                        close(fd);
                        exit(EXIT_FAILURE);
                }
        }

        for (i = 0; i < n_buffers; ++i) {
                struct v4l2_buffer buf;

                CLEAR(buf);

                buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory      = V4L2_MEMORY_MMAP;
                buf.index       = i;

                if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                        perror("VIDIOC_QBUF");
                        close(fd);
                        exit(EXIT_FAILURE);
                }
        }

        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

        if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
                perror("VIDIOC_STREAMON");
                close(fd);
                exit(EXIT_FAILURE);
        }

        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                close(fd);
                exit(EXIT_FAILURE);
        }

        FILE *fp = fopen("image.mjpg", "wb");
        if (!fp) {
                perror("fopen");
                close(fd);
                exit(EXIT_FAILURE);
        }

        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                close(fd);
                exit(EXIT_FAILURE);
        }

        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
                perror("VIDIOC_STREAMOFF");
                close(fd);
                exit(EXIT_FAILURE);
        }

        for (i = 0; i < n_buffers; ++i) {
                munmap(buffers[i].start, buffers[i].length);
        }

        free(buffers);

        close(fd);

        return 0;
}

