        gpioWrite(GREEN_PIN, green_value);
        gpioWrite(BLUE_PIN, blue_value);

        // Wait for 0.005 seconds
        usleep(5000); // 5000 microseconds = 0.005 seconds

        // Toggle color values for the next cycle
