float read_temperature() {
    char device_path[256];
    char w1_slave_path[256];
    FILE *fp;
    char line[256];
    char *token;
    float temperature = -999.0; // Default error value

    // Construct the path to the w1_slave file
    snprintf(device_path, sizeof(device_path), "%s/*", W1_DEVICES_DIR);
    snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/%s", W1_DEVICES_DIR, W1_SLAVE_FILE);

    // Find the DS18B20 device directory
    char *devices = getenv("W1_DEVICES_DIR");
    if (devices == NULL) {
        fprintf(stderr, "Error: W1_DEVICES_DIR environment variable not set.\n");
        return -999.0;
    }

    snprintf(device_path, sizeof(device_path), "%s/*", devices);

    // Iterate through the devices to find the DS18B20
    char **dirs = NULL;
    int num_dirs = 0;
    char **environ_copy = NULL;
    size_t environ_size = 0;
    char **environ = environ;

    // Make a copy of the environment variables
    while (*environ != NULL) {
        environ_size++;
        environ++;
    }

    environ = environ_copy = (char **)malloc(environ_size * sizeof(char *));
    if (environ_copy == NULL) {
        perror("malloc");
        return -999.0;
    }

    size_t i = 0;
    while (i < environ_size) {
        environ[i] = strdup(*environ);
        if (environ[i] == NULL) {
            perror("strdup");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(environ[j]);
            }
            free(environ);
            return -999.0;
        }
        i++;
        environ++;
    }

    // Get a list of all directories in W1_DEVICES_DIR
    char *token_list[] = {device_path, NULL};
    dirs = (char **)token_list;
    num_dirs = 1; // Only one directory to search

    // Iterate through the devices
    for (int i = 0; i < num_dirs; i++) {
        char device_dir[256];
        snprintf(device_dir, sizeof(device_dir), "%s", dirs[i]);

        // Construct the full path to the w1_slave file
        snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/%s", device_dir, W1_SLAVE_FILE);

        // Open the w1_slave file
        fp = fopen(w1_slave_path, "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening %s: %s\n", w1_slave_path, strerror(errno));
            continue; // Try the next device
        }

        // Read the file line by line
        while (fgets(line, sizeof(line), fp) != NULL) {
            // Check for the "YES" flag indicating a valid CRC
            if (strstr(line, "YES") != NULL) {
                // Read the temperature from the next line
                if (fgets(line, sizeof(line), fp) != NULL) {
                    token = strstr(line, "t=");
                    if (token != NULL) {
                        // Extract the temperature value
                        long temp_milli_celsius = strtol(token + 2, NULL, 10);
                        temperature = (float)temp_milli_celsius / 1000.0;
                        break; // Exit the loop after finding the temperature
                    } else {
                        fprintf(stderr, "Error: Could not find temperature value in w1_slave file.\n");
                        fclose(fp);
                        return -999.0;
                    }
                } else {
                    fprintf(stderr, "Error reading temperature from w1_slave file.\n");
                    fclose(fp);
                    return -999.0;
                }
            }
        }

        fclose(fp);
        if (temperature != -999.0) break; // Exit the loop if temperature is found
    }

    // Free the allocated memory
    for (int i = 0; i < environ_size; i++) {
        free(environ_copy[i]);
    }
    free(environ_copy);

    return temperature;
}

