DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int timings[MAX_TIMINGS];
    int i, j;

    // Set GPIO pin as output
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);

    // Set GPIO pin as input
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read timings
    for (i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // Delay 1 microsecond
            if (count > 200) {
                fprintf(stderr, "Timeout waiting for DHT22 response.\n");
                return data; // Return invalid data
            }
        }
        timings[i] = count;
    }

    // Validate checksum
    int checksum = 0;
    for (i = 0; i < 4; i++) {
        checksum += (timings[2 + 4 * i] + timings[3 + 4 * i]) & 0xFF;
    }
    if ((timings[4 + 4 * 4] + timings[5 + 4 * 4]) & 0xFF != checksum) {
        fprintf(stderr, "DHT22 checksum error.\n");
        return data; // Return invalid data
    }

    // Convert data
    data.humidity = (float)(((timings[0] << 8) + timings[1]) & 0xFF) / 10.0;
    data.temperature = (float)(((timings[2] & 0x7F) << 8) + timings[3]) / 10.0;
    if (timings[2] & 0x80) {
        data.temperature *= -1;
    }

    // Validate data
    if (data.temperature < -40 || data.temperature > 80 || data.humidity < 0 || data.humidity > 100) {
        fprintf(stderr, "DHT22 data out of range.\n");
        return data; // Return invalid data
    }

    data.valid = 1;
    return data;
}

