void print_dht22_data(DHT22Data data) {
    if (data.valid) {
        printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", data.temperature, data.humidity);
    } else {
        printf("Invalid DHT22 reading.\n");
    }
}

