    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(PWM1, PI_OUTPUT);
    gpioSetMode(PWM2, PI_OUTPUT);
    gpioSetMode(PWM3, PI_OUTPUT);
    gpioSetMode(PWM4, PI_OUTPUT);
    gpioSetMode(PWM5, PI_OUTPUT);
    gpioSetMode(PWM6, PI_OUTPUT);

    // Set the PWM frequency
    gpioSetPWMfrequency(PWM1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM5, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM6, PWM_FREQUENCY);

    // Set the PWM range
    gpioSetPWMrange(PWM1, PWM_RANGE);
    gpioSetPWMrange(PWM2, PWM_RANGE);
    gpioSetPWMrange(PWM3, PWM_RANGE);
    gpioSetPWMrange(PWM4, PWM_RANGE);
    gpioSetPWMrange(PWM5, PWM_RANGE);
    gpioSetPWMrange(PWM6, PWM_RANGE);

    // Set the PWM duty cycle
    gpioPWM(PWM1, PWM_DUTY_CYCLE);
    gpioPWM(PWM2, PWM_DUTY_CYCLE);
    gpioPWM(PWM3, PWM_DUTY_CYCLE);
    gpioPWM(PWM4, PWM_DUTY_CYCLE);
    gpioPWM(PWM5, PWM_DUTY_CYCLE);
    gpioPWM(PWM6, PWM_DUTY_CYCLE);

    // Main loop
