#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

// Function to read DHT22 data
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[85];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Read 40 bits of data
    for (i = 0; i < 85; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Checksum validation
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -1; // Checksum error
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    for (int i = 0; i < 3; i++) {
        result = read_dht22(DHT22_GPIO, &temperature, &humidity);
        if (result == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT22 read failed\n");
        }
        sleep(60);
    }

    gpioTerminate();
    return 0;
}

