#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_PIN_16 16
#define GPIO_PIN_20 20

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_16;
struct gpiod_line *line_20;

// Signal handler for Ctrl+C
void signal_handler(int sig);

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for GPIO 16 and GPIO 20
    line_16 = gpiod_chip_get_line(chip, GPIO_PIN_16);
    if (!line_16) {
        perror("Error getting GPIO line 16");
        gpiod_chip_close(chip);
        return 1;
    }

    line_20 = gpiod_chip_get_line(chip, GPIO_PIN_20);
    if (!line_20) {
        perror("Error getting GPIO line 20");
        gpiod_line_release(line_16);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_16, "user-space", 0) < 0) {
        perror("Error requesting GPIO line 16 as output");
        gpiod_line_release(line_16);
        gpiod_line_release(line_20);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_20, "user-space", 0) < 0) {
        perror("Error requesting GPIO line 20 as output");
        gpiod_line_release(line_16);
        gpiod_line_release(line_20);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 16 high
        if (gpiod_line_set_value(line_16, 1) < 0) {
            perror("Error setting GPIO 16 high");
            break;
        }

        // Set GPIO 20 low
        if (gpiod_line_set_value(line_20, 0) < 0) {
            perror("Error setting GPIO 20 low");
            break;
        }

        // Print current state to stdout
        printf("GPIO 16: HIGH, GPIO 20: LOW\n");

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds

        // Set GPIO 16 low
        if (gpiod_line_set_value(line_16, 0) < 0) {
            perror("Error setting GPIO 16 low");
            break;
        }

        // Set GPIO 20 high
        if (gpiod_line_set_value(line_20, 1) < 0) {
            perror("Error setting GPIO 20 high");
            break;
        }

        // Print current state to stdout
        printf("GPIO 16: LOW, GPIO 20: HIGH\n");

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line_16);
    gpiod_line_release(line_20);
    gpiod_chip_close(chip);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (line_16) {
        gpiod_line_release(line_16);
    }
    if (line_20) {
        gpiod_line_release(line_20);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit program
    exit(0);
}

#include <stdio.h>
