#include <linux/spi/spidev.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define MAX31855 error codes
#define MAX31855_NO_ERROR 0
#define MAX31855_FAULT 1

// Function to read data from MAX31855
int read_max31855(int fd, uint8_t *data)
{
    struct spi_ioc_transfer transfer = {
        .tx_buf = 0, // No transmit data
        .rx_buf = (unsigned long)data,
        .len = 4, // Read 4 bytes
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return 0;
}

// Function to check for errors in MAX31855 data
int check_max31855_error(uint8_t *data)
{
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return MAX31855_FAULT;
    } else if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return MAX31855_FAULT;
    } else if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return MAX31855_FAULT;
    } else if (data[3] & 0x08) {
        fprintf(stderr, "MAX31855 Fault: Overvoltage\n");
        return MAX31855_FAULT;
    } else if (data[3] & 0x10) {
        fprintf(stderr, "MAX31855 Fault: Under voltage\n");
        return MAX31855_FAULT;
    } else {
        return MAX31855_NO_ERROR;
    }
}

// Function to convert raw data to temperature
float convert_to_temperature(uint8_t *data)
{
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    return raw_temp * 0.25;
}

int main()
{
    int fd;
    uint8_t data[4];
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from MAX31855
        if (read_max31855(fd, data) == 0) {
            // Check for errors
            int error = check_max31855_error(data);
            if (error == MAX31855_NO_ERROR) {
                // Convert to temperature
                float temperature = convert_to_temperature(data);

                // Get current timestamp
                time(&now);
                timeinfo = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Print temperature with timestamp
                printf("%s Temperature: %.2f °C\n", timestamp, temperature);
            } else {
                fprintf(stderr, "Error reading MAX31855 data\n");
            }
        } else {
            fprintf(stderr, "Failed to read from SPI device\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI device (this will never be reached in the current loop)
    close(fd);

    return 0;
}

