#include <time.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define timeout duration (in milliseconds)
#define TIMEOUT_MS 50

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int init_gpio(void);

// Function to trigger the HC-SR04 sensor
int trigger_sensor(void);

// Function to read the echo pin state with timeout
int read_echo(int timeout_ms);

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width_us);

// Function to cleanup GPIO lines and chip
void cleanup_gpio(void);

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Failed to trigger sensor. Retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Read the echo pin state with timeout
        int echo_state = read_echo(TIMEOUT_MS);
        if (echo_state < 0) {
            fprintf(stderr, "Timeout reading echo pin. Retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate the pulse width
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_MS * 1000) {
                echo_state = -1; // Timeout
                break;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (echo_state == -1) {
            echo_state = 1; // Indicate timeout
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        long long start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        long long end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        long long pulse_width_ns = end_ns - start_ns;
        int pulse_width_us = (int)(pulse_width_ns / 1000);

        // Calculate the distance
        float distance = calculate_distance(pulse_width_us);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for 500ms
        usleep(500000);
    }

    return 0;
}

