    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "trigger";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(echo_line, &output_config, 0) != 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line as input
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "echo";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(echo_line, &input_config, 0) != 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to trigger the HC-SR04 sensor
int trigger_sensor(void) {
