    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > timeout_ms * 1000) {
            return -1; // Timeout
        }
    }

    // Wait for echo pin to go low
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > timeout_ms * 1000) {
            return -1; // Timeout
        }
    }

    return 1; // Echo pin is low
}

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width_us) {
    // Speed of sound in air (cm/us) = 0.0343 cm/us
    // Distance = (pulse_width_us * speed_of_sound) / 2
    return (float)pulse_width_us * 0.0343 / 2.0;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio(void) {
    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

