    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d to HIGH: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Read the GPIO value */
    ret = gpiod_line_get_value(line, value_str, sizeof(value_str));
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    /* Print the GPIO value */
    printf("GPIO %d is now HIGH and its value is %s\n", GPIO_PIN, value_str);

    /* Release the GPIO line */
    gpiod_line_release(line);

    /* Close the GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

