#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    int value;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request the GPIO line for output */
    ret = gpiod_line_request_output(line, "my-label", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    /* Set the GPIO output high */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d high: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    /* Read the GPIO value */
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    /* Print the GPIO value */
    printf("GPIO %d value: %d\n", GPIO_PIN, value);

    /* Release the GPIO line */
    gpiod_line_release(line);

    /* Close the GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

