            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance reading\n");
        }

        gpioDelay(500000); // 0.5 seconds
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

