// Define GPIO pins
const int gpio_pins[] = {0, 1, 2, 3, 4, 5, 12, 17};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *lines[8]; // Array to store GPIO lines

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO pin state
int set_gpio_state(int pin, int state);

// Function to report GPIO states
void report_states();

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return 1;
    }

    // Allocate GPIO lines
    for (int i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Could not get GPIO line %d.\n", gpio_pins[i]);
            goto cleanup;
        }
    }

    // Request GPIO lines for output
    for (int i = 0; i < num_pins; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Error: Could not request GPIO line %d for output.\n", gpio_pins[i]);
            goto cleanup;
        }
    }

    // Main loop
    while (1) {
        report_states();
        sleep(1);
    }

cleanup:
    // Release GPIO lines and chip
    for (int i = 0; i < num_pins; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 1;
}

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines and chip
    for (int i = 0; i < num_pins; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set GPIO pin state
int set_gpio_state(int pin, int state)
{
    int index = -1;
    for (int i = 0; i < num_pins; i++) {
        if (gpio_pins[i] == pin) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        fprintf(stderr, "Error: Invalid GPIO pin %d.\n", pin);
        return -1;
    }

    if (gpiod_line_set_value(lines[index], state) < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d to state %d.\n", pin, state);
        return -1;
    }
    return 0;
}

// Function to report GPIO states
void report_states()
{
    printf("GPIO states: ");
    for (int i = 0; i < num_pins; i++) {
        int state = gpiod_line_get_value(lines[i]);
        if (state < 0) {
            fprintf(stderr, "Error: Could not get GPIO line %d value.\n", gpio_pins[i]);
            continue; // Continue to the next pin
        }
        printf("%d=%d ", gpio_pins[i], state);
    }
    printf("\n");
}

