static volatile int terminate = 0;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed, exiting...\n");
    terminate = 1;
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            echo_start_tick = tick;
        }
        else if (level == 0) // Falling edge
        {
            echo_end_tick = tick;

            // Calculate pulse width in microseconds
            int pulse_width = echo_end_tick - echo_start_tick;

            // Calculate distance in centimeters
            float distance = pulse_width * 0.0343 / 2.0;

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        }
    }
}

