// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the TCS34725 sensor
int init_tcs34725(int fd) {
    // Enable the sensor (power on and enable RGBC)
    if (i2c_smbus_write_byte_data(fd, TCS34725_ENABLE, 0x03) < 0) {
        perror("Failed to enable TCS34725");
        return -1;
    }

    // Set integration time (ATIME).  2.4ms * 256 = 614.4ms
    if (i2c_smbus_write_byte_data(fd, TCS34725_ATIME, 0xD5) < 0) {
        perror("Failed to set integration time");
        return -1;
    }

    // Set gain (AGAIN).  60x gain
    if (i2c_smbus_write_byte_data(fd, TCS34725_CONTROL, 0x01) < 0) {
        perror("Failed to set gain");
        return -1;
    }

    return 0;
}

// Function to read RGBC color data from the TCS34725 sensor
int read_tcs34725(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    int ret;

    ret = i2c_smbus_read_word_data(fd, TCS34725_CDATA);
    if (ret < 0) {
        perror("Failed to read clear data");
        return -1;
    }
    *c = (uint16_t)ret;

    ret = i2c_smbus_read_word_data(fd, TCS34725_RDATA);
    if (ret < 0) {
        perror("Failed to read red data");
        return -1;
    }
    *r = (uint16_t)ret;

    ret = i2c_smbus_read_word_data(fd, TCS34725_GDATA);
    if (ret < 0) {
        perror("Failed to read green data");
        return -1;
    }
    *g = (uint16_t)ret;

    ret = i2c_smbus_read_word_data(fd, TCS34725_BDATA);
    if (ret < 0) {
        perror("Failed to read blue data");
        return -1;
    }
    *b = (uint16_t)ret;

    return 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_tcs34725(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    uint16_t r, g, b, c;

    // Main loop
    while (program_running) {
        // Read RGBC color data
        if (read_tcs34725(i2c_fd, &r, &g, &b, &c) == 0) {
            // Print the RGBC values
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Sleep for 0.5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep failed");
        }
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

