// Define GPIO pins for PWM outputs
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle)
{
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Invalid duty cycle value. Must be between 0 and 255.\n");
        return -1;
    }

    gpioPWM(gpio, duty_cycle);
    return 0;
}

int main()
{
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error: Could not register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency for each pin
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Main loop
    while (!terminate) {
        // Set PWM duty cycles for each pin
        if (set_pwm_duty_cycle(PWM_PIN_1, 128) != 0) {
            fprintf(stderr, "Error setting PWM for GPIO %d\n", PWM_PIN_1);
        }
        if (set_pwm_duty_cycle(PWM_PIN_2, 192) != 0) {
            fprintf(stderr, "Error setting PWM for GPIO %d\n", PWM_PIN_2);
        }
        if (set_pwm_duty_cycle(PWM_PIN_3, 64) != 0) {
            fprintf(stderr, "Error setting PWM for GPIO %d\n", PWM_PIN_3);
        }

        // Print the current state of the GPIO pins to stdout
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               PWM_PIN_1, gpioRead(PWM_PIN_1),
               PWM_PIN_2, gpioRead(PWM_PIN_2),
               PWM_PIN_3, gpioRead(PWM_PIN_3));

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

