// Define the GPIO pin for the LED
#define LED_PIN 1

// Define the SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig)
{
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the GPIO pin
int init_gpio(void)
{
    if (wiringPiSetup() == -1)
    {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return -1;
    }

    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW);
    return 0;
}

// Function to read the MCP3008 ADC
int read_adc(int channel)
{
    int fd;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Open the SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0)
    {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    // Transfer the SPI message
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0)
    {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Extract the ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Close the SPI device
    close(fd);

    return adc_value;
}

int main(void)
{
    // Set up signal handling for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Initialize the GPIO pin
    if (init_gpio() == -1)
    {
        return 1;
    }

    printf("Raspberry Pi - GPIO control\n");
    printf("Press CTRL-C to exit!\n");

