#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define CS_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 500000      // 0.5 seconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *cs_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
float measure_distance(void);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
  terminate = 1;
  printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
  // Open GPIO chip
  chip = gpiod_chip_open_by_name("gpiochip0");
  if (!chip) {
    perror("Error opening GPIO chip");
    return -1;
  }

  // Get trigger line
  trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
  if (!trigger_line) {
    perror("Error getting trigger line");
    gpiod_chip_close(chip);
    return -1;
  }

  // Get echo line
  echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
  if (!echo_line) {
    perror("Error getting echo line");
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    return -1;
  }

  // Get CS line
  cs_line = gpiod_chip_get_line(chip, CS_PIN);
  if (!cs_line) {
    perror("Error getting CS line");
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    return -1;
  }

  // Request trigger line for output
  if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
    perror("Error requesting trigger line for output");
    gpiod_line_release(echo_line);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    return -1;
  }

  // Request echo line for input
  if (gpiod_line_request_input(echo_line, "echo") < 0) {
    perror("Error requesting echo line for input");
    gpiod_line_release(trigger_line);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    return -1;
  }

  // Request CS line for output
  if (gpiod_line_request_output(cs_line, "cs", 1) < 0) {
    perror("Error requesting CS line for output");
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    return -1;
  }

  return 0;
}

// Send a trigger pulse
void trigger_pulse(void) {
  gpiod_line_set_value(trigger_line, 1);
  usleep(10); // 10 us pulse
  gpiod_line_set_value(trigger_line, 0);
}

// Measure distance using the HC-SR04
float measure_distance(void) {
  struct gpiod_line_event event;
  struct gpiod_line_event_values values;
  struct timespec start, end;
  long long start_ns, end_ns, diff_ns;
  float distance;

  // Trigger the sensor
  trigger_pulse();

  // Wait for echo to go high with timeout
  clock_gettime(CLOCK_MONOTONIC, &start);
  do {
    if (gpiod_line_event_wait(echo_line, 1, &event) < 0) {
      perror("Error waiting for echo high");
      return -1.0;
    }
    if (gpiod_line_event_get_values(echo_line, &event, &values) < 0) {
      perror("Error getting echo high value");
      return -1.0;
    }
  } while (gpiod_line_get_value(echo_line) == 0 && (clock_gettime(CLOCK_MONOTONIC, &end) == -1 && errno == EINTR));

  if (gpiod_line_get_value(echo_line) == 0) {
    fprintf(stderr, "Timeout waiting for echo high\n");
    return -1.0;
  }

  clock_gettime(CLOCK_MONOTONIC, &start);
  start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;

  // Wait for echo to go low with timeout
  clock_gettime(CLOCK_MONOTONIC, &end);
  end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

  do {
    if (gpiod_line_event_wait(echo_line, 0, &event) < 0) {
      perror("Error waiting for echo low");
      return -1.0;
    }
    if (gpiod_line_event_get_values(echo_line, &event, &values) < 0) {
      perror("Error getting echo low value");
      return -1.0;
    }
  } while (gpiod_line_get_value(echo_line) == 1 && (clock_gettime(CLOCK_MONOTONIC, &end) == -1 && errno == EINTR));

  if (gpiod_line_get_value(echo_line) == 1) {
    fprintf(stderr, "Timeout waiting for echo low\n");
    return -1.0;
  }

  clock_gettime(CLOCK_MONOTONIC, &end);
  end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;

  diff_ns = end_ns - start_ns;

  // Calculate distance in centimeters
  distance = (float)diff_ns / 1000000.0 * SPEED_OF_SOUND / 2.0;

  return distance;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
  if (trigger_line) {
    gpiod_line_release(trigger_line);
  }
  if (echo_line) {
    gpiod_line_release(echo_line);
  }
  if (cs_line) {
    gpiod_line_release(cs_line);
  }
  if (chip) {
    gpiod_chip_close(chip);
  }
}

int main(void) {
  float distance;

  // Install signal handler
  signal(SIGINT, signal_handler);

  // Initialize GPIO
  if (init_gpio() < 0) {
    fprintf(stderr, "GPIO initialization failed\n");
    return 1;
  }

  printf("HC-SR04 Distance Sensor\n");

  // Main loop
  while (!terminate) {
    distance = measure_distance();

    if (distance > 0) {
      printf("Distance: %.2f cm\n", distance);
    } else {
      fprintf(stderr, "Error measuring distance\n");
    }

    usleep(500000); // 0.5 second delay
  }

  // Cleanup GPIO
  cleanup_gpio();

  return 0;
}

