#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_18, *line_23, *line_24;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO output
int set_gpio_output(int gpio, int value);

// Function to report GPIO state
void report_gpio_state(int gpio, int value);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line_18 || !line_23 || !line_24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_18, "my_subsystem", 0) < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_23, "my_subsystem", 0) < 0) {
        perror("Error requesting GPIO 23 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_24, "my_subsystem", 0) < 0) {
        perror("Error requesting GPIO 24 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 18 to 1
        if (set_gpio_output(GPIO_18, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 18\n");
        }
        report_gpio_state(GPIO_18, 1);

        // Set GPIO 23 to 0
        if (set_gpio_output(GPIO_23, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 23\n");
        }
        report_gpio_state(GPIO_23, 0);

        // Set GPIO 24 to 1
        if (set_gpio_output(GPIO_24, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 24\n");
        }
        report_gpio_state(GPIO_24, 1);

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (line_18) gpiod_line_release(line_18);
    if (line_23) gpiod_line_release(line_23);
    if (line_24) gpiod_line_release(line_24);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

// Function to set GPIO output
int set_gpio_output(int gpio, int value) {
    struct gpiod_line *line = NULL;
    if (gpio == GPIO_18) line = line_18;
    else if (gpio == GPIO_23) line = line_23;
    else if (gpio == GPIO_24) line = line_24;
    else {
        fprintf(stderr, "Invalid GPIO number: %d\n", gpio);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to report GPIO state
void report_gpio_state(int gpio, int value) {
    printf("GPIO %d: %d\n", gpio, value);
}

