#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

// Global variables
static int fd ;
static int address ;

// Function prototypes
static int initMPU6050 (void) ;
static int readMPU6050 (int fd, int address, int reg, int *value) ;
static int readMPU6050Data (int fd, int address, int *x, int *y, int *z) ;

// Global variables
static int fd ;
static int address ;

// initMPU6050:
//	Initialise the MPU6050
//
// Returns 0 on success, -1 on failure

static int initMPU6050 (void)
{
  int x ;

  // Wake up the MPU6050
  if (wiringPiI2CWriteReg8 (fd, 0x6B, 0) < 0)
  {
    fprintf (stderr, "MPU6050: Failed to wake up: %s\n", strerror (errno)) ;
    return -1 ;
  }

  // Set the sample rate divider
  if (wiringPiI2CWriteReg8 (fd, 0x19, 0x7F) < 0)
  {
    fprintf (stderr, "MPU6050: Failed to set sample rate: %s\n", strerror (errno)) ;
    return -1 ;
  }

  // Set the full scale range
  if (wiringPiI2CWriteReg8 (fd, 0x1A, 0x00) < 0)
  {
    fprintf (stderr, "MPU6050: Failed to set full scale range: %s\n", strerror (errno)) ;
    return -1 ;
  }

  // Set the DLPF
  if (wiringPiI2CWriteReg8 (fd, 0x1A, 0x00) < 0)
  {
    fprintf (stderr, "MPU6050: Failed to set DLPF: %s\n", strerror (errno)) ;
    return -1 ;
  }

  // Enable the accelerometer
  if (wiringPiI2CWriteReg8 (fd, 0x3E, 0x00) < 0)
  {
    fprintf (stderr, "MPU6050: Failed to enable accelerometer: %s\n", strerror (errno)) ;
    return -1 ;
  }

  // Enable the gyroscope
  if (wiringPiI2CWriteReg8 (fd, 0x3F, 0x00) < 0)
  {
    fprintf (stderr, "MPU6050: Failed to enable gyroscope: %s\n", strerror (errno)) ;
    return -1 ;
  }

  return 0 ;
}

// readMPU6050:
//	Read a single register from the MPU6050
//
// fd:		The file descriptor
// address:	The I2C address of the MPU6050
// reg:		The register to read
// value:	The value to return
//
// Returns 0 on success, -1 on failure

static int readMPU6050 (int fd, int address, int reg, int *value)
{
  int r ;

  r = wiringPiI2CReadReg8 (fd, reg) ;
  if (r < 0)
  {
    fprintf (stderr, "MPU6050: Failed to read register 0x%02X: %s\n", reg, strerror (errno)) ;
    return -1 ;
  }

  *value = r ;
  return 0 ;
}

// readMPU6050Data:
//	Read the accelerometer and gyroscope data from the MPU6050
//
// fd:		The file descriptor
// address:	The I2C address of the MPU6050
// x:		The X value to return
// y:		The Y value to return
// z:		The Z value to return
//
// Returns 0 on success, -1 on failure

static int readMPU6050Data (int fd, int address, int *x, int *y, int *z)
{
  int xh, xl, yh, yl, zh, zl ;

  if (readMPU6050 (fd, address, 0x3B, &xh) < 0) return -1 ;
  if (readMPU6050 (fd, address, 0x3C, &xl) < 0) return -1 ;
  if (readMPU6050 (fd, address, 0x3D, &yh) < 0) return -1 ;
  if (readMPU6050 (fd, address, 0x3E, &yl) < 0) return -1 ;
  if (readMPU6050 (fd, address, 0x3F, &zh) < 0) return -1 ;
  if (readMPU6050 (fd, address, 0x40, &zl) < 0) return -1 ;

  *x = (xh << 8) | xl ;
  *y = (yh << 8) | yl ;
  *z = (zh << 8) | zl ;

  return 0 ;
}

int main (int argc, char *argv[])
{
  int x, y, z ;
  int i ;

  if (argc != 2)
  {
    fprintf (stderr, "Usage: %s <i2c-device>\n", argv[0]) ;
    exit (EXIT_FAILURE) ;
  }

  wiringPiSetup () ;

  fd = wiringPiI2CSetupInterface (argv[1], 0x68) ;
  if (fd < 0)
  {
    fprintf (stderr, "Failed to open the I2C device: %s\n", strerror (errno)) ;
    exit (EXIT_FAILURE) ;
  }

  if (initMPU6050 () < 0)
  {
    fprintf (stderr, "Failed to initialise the MPU6050\n") ;
    exit (EXIT_FAILURE) ;
  }

  for (;;)
  {
    if (readMPU6050Data (fd, 0x68, &x, &y, &z) < 0)
    {
      fprintf (stderr, "Failed to read MPU6050 data\n") ;
      exit (EXIT_FAILURE) ;
    }

    printf ("X: %6d, Y: %6d, Z: %6d\n", x, y, z) ;
    delay (1000) ;
  }

  return 0 ;
}

